const scheduledJobRepositoryIDs = `-- name: ScheduledJobRepositoryIDs :many
SELECT id FROM code_repositories WHERE workspace_id=$1 ORDER BY id
`

func (q *Queries) ScheduledJobRepositoryIDs(ctx context.Context, workspaceID string) ([]string, error) {
	rows, err := q.db.Query(ctx, scheduledJobRepositoryIDs, workspaceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

