const updateScheduledJob = `-- name: UpdateScheduledJob :execrows
UPDATE scheduled_jobs SET revision=revision+1,authorized_by=$3,definition=$4,enabled=$5,next_due_at=$6
WHERE workspace_id=$1 AND id=$2 AND revision=$7
`

type UpdateScheduledJobParams struct {
	WorkspaceID  string             `json:"workspace_id"`
	ID           string             `json:"id"`
	AuthorizedBy string             `json:"authorized_by"`
	Definition   []byte             `json:"definition"`
	Enabled      bool               `json:"enabled"`
	NextDueAt    pgtype.Timestamptz `json:"next_due_at"`
	Revision     int64              `json:"revision"`
}

func (q *Queries) UpdateScheduledJob(ctx context.Context, arg UpdateScheduledJobParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateScheduledJob,
		arg.WorkspaceID,
		arg.ID,
		arg.AuthorizedBy,
		arg.Definition,
		arg.Enabled,
		arg.NextDueAt,
		arg.Revision,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
